import{_ as t,a as d}from"./chunks/scalar_atomic_operation_diagram.BtH00wBQ.js";import{_ as e,o,a as c,b as _}from"./app.UgfkfLuP.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"原子操作","link":"/api/SIMD-API/c_api/atomic/atomic"},{"text":"原子操作概述","link":"/api/SIMD-API/c_api/atomic/atomic_operations_overview"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/atomic/atomic_operations_overview.md","filePath":"api/SIMD-API/c_api/atomic/atomic_operations_overview.md","lastUpdated":1790760963000}'),r={name:"api/SIMD-API/c_api/atomic/atomic_operations_overview.md"};function s(i,a,l,m,n,v){return o(),c("div",null,[...a[0]||(a[0]=[_('<div><article class="markdown-body"><h1>原子操作概述</h1><p>数据搬运随路原子操作接口用于对后续目的地址为GM的数据搬运指令开启原子操作，涉及的接口请参见<a href="#datamove_atomic_operation_interface">表1</a>。如下图1的左侧子图所示，未开启原子操作时，写入GM的数据搬运完成后，GM中原始数据将被新搬运数据完全覆盖。如图1右侧子图所示，当数据搬运随路原子操作接口被调用后，系统将为后续写入GM的数据搬运开启原子操作。此时，数据搬运完成后，GM中的最终数据由原始GM数据与新搬运数据共同决定。</p><p><strong>图1</strong> 数据搬运随路原子累加效果</p><p><img src="'+t+'" alt title="数据搬运随路原子累加效果"></p><p><strong>表1</strong> 数据搬运随路原子操作接口<a id="datamove_atomic_operation_interface"></a></p><table><thead><tr><th>对应接口</th><th>接口功能描述</th></tr></thead><tbody><tr><td><a href="datamove_atomic/asc_set_atomic_add.html">asc_set_atomic_add</a></td><td>对后续目的地址为GM的数据搬运开启原子累加。原子累加过程：将待拷贝的内容和GM已有内容进行求和，然后将求和结果写入GM。</td></tr><tr><td><a href="datamove_atomic/asc_set_atomic_max.html">asc_set_atomic_max</a></td><td>设置后续搬运到GM的数据是否执行原子比较：将待拷贝的内容和GM已有内容进行比较，然后将最大值写入GM。</td></tr><tr><td><a href="datamove_atomic/asc_set_atomic_min.html">asc_set_atomic_min</a></td><td>设置后续搬运到GM的数据是否执行原子比较：将待拷贝的内容和GM已有内容进行比较，然后将最小值写入GM。</td></tr><tr><td><a href="datamove_atomic/asc_disable_dma_atomic.html">asc_disable_dma_atomic</a></td><td>关闭数据搬运随路原子操作功能。</td></tr></tbody></table><p>Scalar原子操作接口，能够在指定GM地址上进行单点原子计算操作，涉及的接口请参见<a href="#scalar_atomic_operation_interface">表2</a>。</p><p>标量原子操作与数据搬运随路原子操作相比，两者的差异如下：</p><ul><li>数据搬运随路原子操作的对象是搬运的Tensor，需要先调用数据搬运随路原子操作接口开启原子操作，开启后对后续通过MTE单元搬运到GM的整个Tensor生效，会影响后续搬运指令的行为。</li><li>标量原子操作的对象是传入的GM地址上的单个元素，无需开启配置，仅对本次调用传入的GM地址上的单个元素生效，不会影响后续搬运指令。</li></ul><p>如下图2左侧子图所示，不使用<code>asc_atomic_add</code>接口时，多个AI Core同时对同一GM地址执行累加操作会相互覆盖，操作不具备原子性，最终结果不可预期。如右侧子图所示，使用<code>asc_atomic_add</code>接口后，各AI Core的累加操作串行化执行，确保每次累加操作的原子性，最终结果符合预期。</p><p><strong>图2</strong> 标量原子累加效果<a id="scalar_atomic_operation_diagram"></a></p><p><img src="'+d+'" alt title="标量原子累加效果"></p><p><strong>表2</strong> Scalar原子操作接口<a id="scalar_atomic_operation_interface"></a></p><table><thead><tr><th>对应接口</th><th>接口功能描述</th></tr></thead><tbody><tr><td><a href="scalar_atomic/asc_atomic_add.html">asc_atomic_add</a></td><td>用于在指定GM地址上进行原子加操作，将address指向的GM地址上的旧值（<code>old_value</code>）与输入标量值（value）求和，将和结果（<code>new_value</code>）写回GM地址，返回该地址修改前的值（<code>old_value</code>）。</td></tr><tr><td><a href="scalar_atomic/asc_atomic_min.html">asc_atomic_min</a></td><td>用于在指定GM地址上进行原子取最小值操作，将address指向的GM地址上的旧值（<code>old_value</code>）与输入标量值（value）做比较，将较小值（<code>new_value</code>）写回GM地址，返回该地址修改前的值（<code>old_value</code>）。</td></tr><tr><td><a href="scalar_atomic/asc_atomic_max.html">asc_atomic_max</a></td><td>用于在指定GM地址上进行原子取大操作，将address指向的GM地址上的旧值（<code>old_value</code>）与输入的标量值（value）进行比较，将较大值（<code>new_value</code>）写回GM地址，返回该地址修改前的值（<code>old_value</code>）。</td></tr><tr><td><a href="scalar_atomic/asc_atomic_cas.html">asc_atomic_cas</a></td><td>在指定GM地址上进行原子比较操作，读取address指向的GM地址上的旧值（<code>old_value</code>）与输入标量值value1进行比较：如果相等，则将输入标量值value2写入GM地址；如果不相等，则GM地址上的值保持不变。返回该地址修改前的值（<code>old_value</code>）。</td></tr><tr><td><a href="scalar_atomic/asc_atomic_exch.html">asc_atomic_exch</a></td><td>用于在GM内存中执行原子交换操作，读取address指向的GM地址上的旧值（<code>old_value</code>），并将输入的标量值（value）替换旧值存储回同一地址，返回该地址修改前的值（<code>old_value</code>）。</td></tr><tr><td><a href="scalar_atomic/asc_atomic_and.html">asc_atomic_and</a></td><td>对GM中的数据与指定数据执行原子与操作，即将val按位与到address指向的数据元素上。读取address指向的GM地址上的旧值（<code>old_value</code>），将旧值与输入标量值val进行按位与运算，将结果（<code>new_value</code>）写回GM地址，返回该地址修改前的值（<code>old_value</code>）。</td></tr><tr><td><a href="scalar_atomic/asc_atomic_inc.html">asc_atomic_inc</a></td><td>对GM中address指向的计数器执行原子递增操作，如果address上的数值大于等于指定数值val，则对address赋值为0，否则将address上数值加1，返回该地址修改前的值（<code>old_value</code>）。</td></tr><tr><td><a href="scalar_atomic/asc_atomic_dec.html">asc_atomic_dec</a></td><td>对GM中address指向的计数器执行原子递减操作，如果address上的数值等于0或大于指定数值val，则对address赋值为val，否则将address上数值减1，返回该地址修改前的值（<code>old_value</code>）。</td></tr><tr><td><a href="scalar_atomic/asc_atomic_or.html">asc_atomic_or</a></td><td>对GM中的数据与指定数据执行原子或操作，即将val按位或到address指向的数据元素上。读取address指向的GM地址上的旧值（<code>old_value</code>），将旧值与输入标量值val进行按位或运算，将结果（<code>new_value</code>）写回GM地址，返回该地址修改前的值（<code>old_value</code>）。</td></tr><tr><td><a href="scalar_atomic/asc_atomic_sub.html">asc_atomic_sub</a></td><td>对GM中的数据与指定数据执行原子减操作，即将val从address指向的数据元素上减去。读取address指向的GM地址上的旧值（<code>old_value</code>），将旧值减去输入标量值val，将结果（<code>new_value</code>）写回GM地址，返回该地址修改前的值（<code>old_value</code>）。</td></tr><tr><td><a href="scalar_atomic/asc_atomic_xor.html">asc_atomic_xor</a></td><td>对GM中的数据与指定数据执行原子异或操作，即将val按位异或到address指向的数据元素上。读取address指向的GM地址上的旧值（<code>old_value</code>），将旧值与输入标量值val进行按位异或运算，将结果（<code>new_value</code>）写回GM地址，返回该地址修改前的值（<code>old_value</code>）。</td></tr><tr><td><a href="scalar_atomic/asc_set_store_atomic_config_v1.html">asc_set_store_atomic_config_v1</a></td><td>设置标量原子操作配置：操作类型（仅支持求和操作）和数据类型。</td></tr><tr><td><a href="scalar_atomic/asc_get_store_atomic_config.html">asc_get_store_atomic_config</a></td><td>获取asc_set_store_atomic_config_v1设置的标量原子操作配置。</td></tr></tbody></table></article></div>',1)])])}const G=e(r,[["render",s]]);export{h as __pageData,G as default};
